(()=>{'use strict';const $=id=>document.getElementById(id);if(!$('freestyle'))return;
const prompts=['What did you leave unsaid today? Start with: “I kept quiet when…”','Describe your street after midnight. Let three details become three bars.','Speak to your younger self. What do you wish someone had told you?','Pick an object in the room. Tell its story, then tell yours.','Start with “Behind the mask…” and follow the first thought.','Give a feeling a colour, a place and a sound. Rap the scene.','What are you carrying that you could put down? No need to explain it perfectly.','Make four lines from these words: concrete, breath, mirror, dawn.','Say one thing you appreciate today. Keep it specific.','Start with “I don’t have the answer…” and let the next line surprise you.'];let index=0;
$('ug-shuffle').onclick=()=>{index=(index+1+Math.floor(Math.random()*(prompts.length-1)))%prompts.length;$('ug-prompt').textContent=prompts[index];};
let recorder,stream,timer,url,started,busy=false;const status=t=>$('ug-status').textContent=t;const release=()=>{stream?.getTracks().forEach(t=>t.stop());stream=null;clearInterval(timer);$('ug-booth').classList.remove('is-recording');};const clear=()=>{if(url)URL.revokeObjectURL(url);url=null;$('ug-audio').removeAttribute('src');$('ug-audio').load();$('ug-playback').hidden=true;};
$('ug-record').onclick=async()=>{if(busy||recorder?.state==='recording')return;if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){status('Recording is unavailable in this browser. Use your phone’s voice recorder instead.');return;}busy=true;$('ug-record').disabled=true;status('Waiting for microphone permission…');try{stream=await navigator.mediaDevices.getUserMedia({audio:true});recorder=new MediaRecorder(stream);let chunks=[];recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onstop=()=>{const type=recorder.mimeType||chunks[0]?.type||'audio/webm';const blob=new Blob(chunks,{type});clear();if(blob.size){url=URL.createObjectURL(blob);$('ug-audio').src=url;$('ug-download').href=url;$('ug-download').download='caisik-raw-take-'+Date.now()+(/mp4/.test(type)?'.m4a':/ogg/.test(type)?'.ogg':'.webm');$('ug-playback').hidden=false;status('Your take is ready. Listen back, keep one honest line, and download to keep the audio.');}else status('No audio was captured. Try again.');release();$('ug-stop').disabled=true;$('ug-record').disabled=false;};recorder.onerror=()=>{release();status('Recording failed. Try again or use your phone recorder.');$('ug-record').disabled=false;$('ug-stop').disabled=true;};recorder.start();started=Date.now();$('ug-time').textContent='00:00';$('ug-stop').disabled=false;$('ug-booth').classList.add('is-recording');status('Recording your microphone. Keep going — silence and imperfect lines belong here too.');timer=setInterval(()=>{let sec=Math.floor((Date.now()-started)/1000);$('ug-time').textContent=String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0');if(sec>=300)$('ug-stop').click();},250);}catch(e){release();$('ug-record').disabled=false;status('Microphone unavailable or permission declined. Check browser permissions or use your phone recorder.');}finally{busy=false;}};
$('ug-stop').onclick=()=>{if(recorder?.state==='recording'){recorder.stop();$('ug-stop').disabled=true;release();}};$('ug-clear').onclick=()=>{clear();status('Take deleted from this tab. Ready when you are.');};window.addEventListener('pagehide',()=>{if(recorder?.state==='recording')recorder.stop();release();});})();
